CREATE TABLE ODS_XDAY_JY.ODS_JY_SM_PLEDREPPD_PFD (
   ID  DECIMAL(19,0) COMMENT 'ID',
   ENDDATE  STRING COMMENT '日期',
   INFOSOURCE  STRING COMMENT '信息来源',
   INNERCODE  STRING COMMENT '证券内部编码',
   SECUCODE  STRING COMMENT '证券代码',
   SECUABBR  STRING COMMENT '证券简称',
   NONPLEDVOLUME  DECIMAL(19,2) COMMENT '无限售股份质押数量(万股)',
   RESPLEDVOLUME  DECIMAL(19,2) COMMENT '有限售股份质押数量(万股)',
   TOTALSHAREA  DECIMAL(19,2) COMMENT 'A股总股本(万股)',
   PLEDGENUM  DECIMAL(10,0) COMMENT '质押笔数',
   PLEDGERATIO  DECIMAL(8,4) COMMENT '质押比例(%)',
   UPDATETIME  STRING COMMENT '更新时间',
   JSID  DECIMAL(19,0) COMMENT 'JSID',
   LD_TIME  STRING COMMENT '加载时间'
)
COMMENT '股票质押回购质押明细'
PARTITIONED BY ( P_DT  STRING)
ROW FORMAT DELIMITED FIELDS TERMINATED BY '\t' NULL DEFINED AS '' ; ;

